  function targetOf(it) { try { return String(typeof it.cmd === "function" ? it.cmd() || "" : it.cmd || ""); } catch (e) { return ""; } }
  // "Delete note" → "delete note", "Restart…" → "restart"; a first word in capitals (PDF) keeps them
  function actionOf(label) { var l = String(label || "").replace(/(…|\.\.\.)\s*$/, "").trim(); return /^[A-Z][a-z]/.test(l) ? l.charAt(0).toLowerCase() + l.slice(1) : l; }
