  function spotlightOpen() { try { return !!(A.spotlight && A.spotlight.isOpen && A.spotlight.isOpen()); } catch (e) { return false; } }
  function launchpadOpen() { try { return !!(A.launchpad && A.launchpad.isOpen && A.launchpad.isOpen()); } catch (e) { return false; } }
