    el.innerHTML = '<div class="lg-clock"><div class="lg-d">' + esc(c.d) + '</div><div class="lg-t">' + c.t + "</div></div>" +
      '<form class="lg-user" autocomplete="off"><span class="lg-av" style="background:' + (/^#[0-9a-f]{3,8}$/i.test(color) ? color : PAL[0]) + '">' + esc(name.charAt(0).toUpperCase()) + "</span>" +
      '<span class="lg-row"><span class="lg-n">' + esc(name) + '</span><button type="submit" class="lg-go" aria-label="Log in" title="Log in (Return)">' + A.icon("forward", 14) + "</button></span></form>" +
      '<div class="lg-p"><button type="button" data-p="reboot">' + A.icon("restart", 18) + '<span>Restart</span></button><button type="button" data-p="off">' + A.icon("power", 18) + "<span>Shut down</span></button></div>";
    el.querySelector("form").onsubmit = function (e) { e.preventDefault(); SH.unlock(); };
    // Restart and Shut Down are two-step: the first press asks, the second acts (2.6 s)
    el.querySelectorAll("[data-p]").forEach(function (b) {
      var lab = b.querySelector("span"), orig = lab.textContent, t = 0;
      b.onclick = function () {
        if (!b.classList.contains("armed")) { b.classList.add("armed"); lab.textContent = "Press again"; clearTimeout(t); t = setTimeout(function () { b.classList.remove("armed"); lab.textContent = orig; }, 2600); return; }
        SH.power(b.getAttribute("data-p"));
      };
    });
