    ".te-ta, .te-hl { position: absolute; left: 0; top: 0; width: 100%; height: 100%; box-sizing: border-box; display: block; margin: 0; border: 0; border-radius: 0; padding: 30px var(--te-pad) 56px; font: 400 var(--te-fs)/var(--te-lh) var(--mono); letter-spacing: 0; word-spacing: 0; text-indent: 0; text-transform: none; text-align: left; font-variant-ligatures: none; font-feature-settings: normal; tab-size: 4; white-space: pre-wrap; overflow-wrap: break-word; word-break: normal; overflow-x: hidden; scrollbar-gutter: stable; -webkit-font-smoothing: antialiased }",
    ".te-ta { z-index: 1; overflow-y: auto; background: transparent; color: var(--ink); caret-color: var(--ink); resize: none; outline: none; -webkit-appearance: none; appearance: none }",
