    ".te-pv:focus-visible { outline: none }",
    ".te-pv .rich { font-size: calc(var(--te-n) * 14px / 13); line-height: 1.62; max-width: 100% }",
    ".te-pv .rich h1 { font-size: calc(var(--te-n) * 28px / 13); line-height: 1.02; letter-spacing: -0.025em; margin: 0 0 .75em }",
    ".te-pv .rich h2 { font-size: calc(var(--te-n) * 20px / 13); line-height: 1.1; letter-spacing: -0.02em }",
    ".te-pv .rich pre, .te-pv .rich code { font-size: .89em }",
