    ".te-pv .rich a { cursor: pointer }",
    ".te-pv .rich li.ck { cursor: default }",
    ".te-pv-empty { margin: 0; font: 400 13px/20px var(--sans); color: var(--muted) }",
    // the status line: Swiss small type on the text's own left edge
    ".te-st { flex: none; display: flex; align-items: center; gap: 10px; height: 32px; padding: 0 var(--te-pad); font: 400 var(--te-fs)/1 var(--mono) }",
    ".te-pos { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font: 500 11px/16px var(--sans); letter-spacing: .01em; color: var(--muted); font-variant-numeric: tabular-nums }",
    ".te-dot, .te-lock { flex: none; width: 22px; height: 22px; margin: 0 -4px; display: inline-grid; place-items: center; border-radius: 999px; color: var(--muted) }",
    ".te-dot:hover, .te-lock:hover { background: rgba(35,34,29,.06) }",
    ".te-dot .sdot { vertical-align: 0 }",
    ".te-st .seg { flex: none; padding: 2px }",
