    ".te-find { flex: none; display: grid; grid-template-columns: 28px minmax(0, 1fr) auto; align-items: center; gap: 6px; padding: 8px 10px; background: var(--surface); border-bottom: 1px solid var(--line); animation: te-drop .22s var(--ease) both }",
    ".te-find .te-row2 { display: contents }",
