  function cmdOf(line) {
    var s = String(line || "").replace(/^\s*(?:\$|%|~[^\s›]*\s*›|[\w./-]+\s›)\s+/, "");
    s = s.slice(0, cmdEnd(s)).trim();
    if (!s || s.charAt(0) === "#") return null;
    var first = s.split(/[\s|;&<>()]/)[0];
    return runnable(first) && !readsLikeProse(s) ? s : null;
  }
  // in running prose, program names (not everyday words) become links to their pages; flags and paths are set in mono
  function prose(text, self) {
    return esc(text).replace(/(^|[\s(“'])([a-z][\w-]*[a-z0-9])(?=$|[\s.,;:!?)”'])/g, function (m, pre, w) {
      return pre + (w !== self && !PLAIN[w] && isProg(w) ? linkHTML("man:" + w, w) : w);
    }).replace(/(^|[\s(“])(--?[A-Za-z][\w-]*|~?\/[\w.~*\/-]*[\w*~\/])(?=$|[\s,;:!?)”]|\.(?:\s|$))/g, "$1<code>$2</code>");
  }
  function lev(a, b) {
    if (Math.abs(a.length - b.length) > 2) return 9;
    var p = [], i, j;
    for (j = 0; j <= b.length; j++) p[j] = j;
    for (i = 1; i <= a.length; i++) { var prev = p[0]; p[0] = i; for (j = 1; j <= b.length; j++) { var tmp = p[j]; p[j] = Math.min(p[j] + 1, p[j - 1] + 1, prev + (a.charAt(i - 1) === b.charAt(j - 1) ? 0 : 1)); prev = tmp; } }
    return p[b.length];
  }
  function allNames() {
    var seen = {};
    Object.keys(K.bin).concat(Object.keys(A.sh.builtins)).forEach(function (n) { if (/^[\w][\w.+-]*$/.test(n)) seen[n] = 1; });
    listDir(MANDIR).forEach(function (e) { if (/\.md$/.test(e.name)) seen[e.name.replace(/\.md$/, "")] = 1; });
    return Object.keys(seen).sort();
  }

  /* ==========================================================================
     Rendering: one page per kind
     ========================================================================== */
  // A.md leaves links it does not know as text: [text](href) and ![alt](src) become ours (not inside code)
  // Runs on HTML that A.md already produced: existing tags are left whole, and a target may never contain markup or
  // a quote, so a crafted [text](target) cannot reach into a generated tag and become an attribute of its own.
  function linkify(html) {
    return html.split(/(<pre>[\s\S]*?<\/pre>|<a [^>]*>[\s\S]*?<\/a>)/).map(function (seg, i) {
      if (i % 2) return seg;
      var codes = [];
      seg = seg.replace(/<code>[\s\S]*?<\/code>/g, function (m) { codes.push(m); return "\u0001" + (codes.length - 1) + "\u0001"; });
      seg = seg.replace(/!\[([^\]]*)\]\(([^)\s"'<>]+)\)/g, function (m, alt, src) { return '<img class="pv-inl" alt="' + esc(alt.replace(/<[^>]*>/g, "")) + '" data-src="' + src + '">'; });
      seg = seg.replace(/\[([^\]]+)\]\(((?:cmd|ask):[^)"'<>]+|[^)\s"'<>]+)\)/g, function (m, text, href) { return '<a class="pv-a" data-href="' + href + '" tabindex="0" role="link">' + text + "</a>"; });
      return seg.replace(/\u0001(\d+)\u0001/g, function (m, n) { return codes[+n]; });
    }).join("");
  }
  function enhance(root, ctx) {
    ctx = ctx || {};
    var q = function (s) { return Array.prototype.slice.call(root.querySelectorAll(s)); };
    // web links: Atlas has no network; Claude is the only way out
    q("a[href]").forEach(function (a) {
      var href = a.getAttribute("href");
      a.removeAttribute("href"); a.removeAttribute("target"); a.removeAttribute("rel");
      a.className = "pv-a web"; a.setAttribute("data-href", href); a.tabIndex = 0; a.setAttribute("role", "link");
      a.title = A.claude ? "Ask Claude about this link" : "Atlas has no network";
    });
    q("h1, h2, h3").forEach(function (h) { h.setAttribute("data-anchor", slug(h.textContent)); });
    // inline code that names a program or a manual page links to that page
    q("code").forEach(function (c) {
      if (c.closest("pre") || c.closest("a")) return;
      var t = c.textContent.trim(), m = /^man\s+([\w][\w.+-]*)$/.exec(t), name = m ? m[1] : t;
      if (!/^[\w][\w.+-]*$/.test(name) || name === ctx.self || !manExists(name)) return;
      var a = el("a", "pv-a"); a.setAttribute("data-href", "man:" + name); a.tabIndex = 0; a.setAttribute("role", "link");
      c.parentNode.insertBefore(a, c); a.appendChild(c);
    });
    // code blocks: every line that is a command can be typed into Terminal
    q("pre").forEach(function (pre) {
      if (pre.classList.contains("pv-syn")) return;
      var prev = pre.previousElementSibling;
      if (prev && /^H[1-3]$/.test(prev.tagName) && /^synopsis$/i.test(prev.textContent.trim())) return;
      var code = pre.querySelector("code") || pre, lines = code.textContent.replace(/\n$/, "").split("\n"), any = false;
      var html = lines.map(function (l) { var c = cmdOf(l); if (c) any = true; return c ? '<span class="pv-cmd" tabindex="0" data-cmd="' + esc(c) + '">' + esc(l) + "</span>" : esc(l); }).join("\n");
      if (any) code.innerHTML = html;
    });
    // pictures from the disk; there is no network to fetch others
    q("img.pv-inl").forEach(function (img) {
      var src = img.getAttribute("data-src") || "", abs = null, im = null;
      if (/^data:image\//i.test(src)) { img.src = src; img.removeAttribute("data-src"); return; }
      if (!/^[a-z][a-z0-9+.-]*:/i.test(src) || /^file:/i.test(src)) abs = resolveFrom(ctx.base, src);
      if (abs && FS.exists(abs) && !FS.isDir(abs)) im = imageOf(abs);
      if (im) { img.src = im.src; img.removeAttribute("data-src"); img.setAttribute("data-path", abs); if (im.w) { img.width = Math.round(im.w); img.height = Math.round(im.h); } return; }
      img.parentNode.replaceChild(el("span", "pv-noimg", esc(img.getAttribute("alt") || src)), img);
    });
    // a manual page's SEE ALSO: every name is a link
    if (ctx.man) q("h3").forEach(function (h) {
      if (!/^see also$/i.test(h.textContent.trim())) return;
      var p = h.nextElementSibling; if (!p || p.tagName !== "P") return;
      p.innerHTML = p.textContent.split(/\s*,\s*/).map(function (item) {
        item = item.trim(); var m = /^(?:man\s+)?([\w][\w.+-]*)$/.exec(item);
        return m && m[1] !== ctx.self && manExists(m[1]) ? linkHTML("man:" + m[1], esc(item)) : esc(item);
      }).join(", ");
    });
  }
  function resolveFrom(base, href) {
    var h = String(href || "").replace(/^file:\/\//i, "").replace(/[?#].*$/, "");
    try { h = decodeURI(h); } catch (e) {}
    if (!h) return null;
    if (h === "~" || h.indexOf("~/") === 0) return FS.norm(HOME + h.slice(1));
    if (h.charAt(0) === "/") return FS.norm(h);
    return FS.resolve(base || HOME, h);
  }
  // the text a page is drawn from, read once per drawing and kept: a page whose file was deleted can still re-sort it
  function textOf(info) { if (info.text == null) info.text = info.path ? readText(info.path) || "" : ""; return info.text; }
  function buildMarkdown(info) {
    var root = el("div", "rich pv-doc pv-md" + (info.man != null ? " pv-man" : ""));
    root.innerHTML = linkify(A.md(textOf(info)));
    enhance(root, { base: info.base, man: info.man != null, self: info.man || null });
    return root;
  }

  /* ---------- manual pages built from a program's metadata, section for section as `man` prints them ---------- */
  function buildMan(name, x) {
    var root = el("div", "rich pv-doc pv-man"), entry = own(K.bin, name) ? K.bin[name] : null;
    if (x.alias) x = (own(K.bin, x.alias) && K.bin[x.alias]) || x;
    var m = x.man || {};
    var about = m.about ? prose(m.about, name) : x.builtin ? "A shell builtin: it runs inside the shell itself, so it can change the shell's own state."
      : esc(capital(x.desc || name)) + ". Run <code>" + esc(name) + " --help</code> for its usage line.";
    var h = "<h1>" + esc(name) + "</h1>";
    h += "<h3>Name</h3><p>" + esc(name) + " — " + esc(x.desc || "") + "</p>";
    h += '<h3>Synopsis</h3><pre class="pv-syn"><code>' + esc(x.usage || name) + "</code></pre>";
    h += "<h3>Description</h3><p>" + about + "</p>";
    if (m.options && m.options.length) h += '<h3>Options</h3><dl class="pv-opts">' + m.options.map(function (o) { return "<dt>" + esc(o[0]) + "</dt><dd>" + prose(o[1] || "", name) + "</dd>"; }).join("") + "</dl>";
    if (m.examples && m.examples.length) h += '<h3>Examples</h3><div class="pv-exs">' + m.examples.map(function (e) {
      return '<div class="pv-ex"><code class="pv-cmd" tabindex="0" data-cmd="' + esc(e[0]) + '">' + esc(e[0]) + "</code>" + (e[1] ? '<p class="pv-exd">' + prose(e[1], name) + "</p>" : "") + "</div>";
    }).join("") + "</div>";
    if (name === "help") { var ix = indexHTML(); h += ix.html; root.style.setProperty("--pv-idx-w", ix.w + "ch"); }
    var also = ((entry && entry.see) || []).concat(["help", "atlas"]).filter(function (s, i, a) { return a.indexOf(s) === i; });
    h += "<h3>See also</h3><p>" + also.map(function (s) { return s === name ? esc(s) : linkHTML("man:" + s, esc(s)); }).join(", ") + "</p>";
    root.innerHTML = h;
    return root;
  }
  // every command, by the categories `help` uses; w is the longest name, so every section shares one column
  function idxRows(list) { return '<dl class="pv-idx">' + list.map(function (x) { return "<dt>" + linkHTML("man:" + x[0], esc(x[0])) + '</dt><dd title="' + esc(x[1] || "") + '">' + esc(x[1] || "") + "</dd>"; }).join("") + "</dl>"; }
  function indexHTML(extra) {
    var cats = {}, order = ["Shell", "Files", "Text", "System", "Apps", "Desktop", "Claude"], w = 4;
    var push = function (c, n, d) { (cats[c] = cats[c] || []).push([n, d]); w = Math.max(w, n.length); };
    Object.keys(A.sh.builtins).forEach(function (n) { if (/^[\w]/.test(n)) push("Shell", n, A.sh.builtins[n].desc); });
    Object.keys(K.bin).forEach(function (n) { var b = K.bin[n]; if (b.alias || b.external || b.hidden || n === "sh" || n === "login") return; push(b.cat || "Other", n, b.desc); });
    (extra || []).forEach(function (x) { w = Math.max(w, x[0].length); });
    var html = order.concat(Object.keys(cats).filter(function (c) { return order.indexOf(c) < 0; }).sort()).map(function (c) {
      var list = cats[c]; if (!list) return "";
      list.sort(function (a, b) { return a[0] < b[0] ? -1 : 1; });
      return "<h3>" + esc(c) + "</h3>" + idxRows(list);
    }).join("");
    return { html: html, w: Math.min(w, 18) };
  }
  function buildIndex() {
    var root = el("div", "rich pv-doc pv-man pv-index");
    var pages = listDir(MANDIR).filter(function (e) { return /\.md$/.test(e.name); }).map(function (e) {
      var n = e.name.replace(/\.md$/, ""), t = readText(e.path) || "", m = /#{1,3}\s*Name\s*\n+\s*([^\n]+)/i.exec(t);
      return [n, m ? m[1].replace(/^[\w.+-]+\s+[—-]\s+/, "") : ""];
    });
    var ix = indexHTML(pages);
    root.style.setProperty("--pv-idx-w", ix.w + "ch");
    root.innerHTML = "<h1>Manual</h1><p>Everything in Atlas is a command. Type a name to run it, add <code>--help</code> for its usage, or read its page here. Names on these pages are links; Back and Forward work as in a browser.</p>" +
      (pages.length ? "<h3>Pages</h3>" + idxRows(pages) : "") + ix.html;
    return root;
  }
  function buildNoMan(name) {
    var root = el("div", "rich pv-doc pv-man"), low = name.toLowerCase();
    var near = allNames().filter(function (n) { return n !== name && (n.indexOf(low) >= 0 || (low.length > 2 && low.indexOf(n) >= 0 && n.length > 2) || lev(low, n) <= (low.length > 4 ? 2 : 1)); }).slice(0, 8);
    root.innerHTML = "<h1>" + esc(name) + "</h1><p>No manual entry for " + esc(name) + ".</p>" +
      (near.length ? "<h3>Did you mean</h3><p>" + near.map(function (n) { return linkHTML("man:" + n, esc(n)); }).join(", ") + "</p>" : "") +
      "<h3>See also</h3><p>" + linkHTML("man:", "all commands") + ", " + linkHTML("man:atlas", "atlas") + "</p>";
    return root;
  }

  /* ---------- the start page: pictures, answers, recent pages and the manual ---------- */
  function row(path, thumb, name, meta) {
    return '<a class="pv-a pv-row" data-href="' + esc(path) + '" tabindex="0" role="link"><span class="pv-th">' + thumb + '</span><span class="pv-rn">' + esc(name) + '</span><span class="pv-rm">' + esc(meta) + "</span></a>";
  }
  function answerTitle(path) { var t = readText(path) || "", m = /^#\s+(.+)$/m.exec(t.slice(0, 600)); return m ? m[1].trim() : FS.basename(path).replace(/\.md$/, ""); }
  function buildHome() {
    var root = el("div", "rich pv-doc pv-home"), h = "<h1>Preview</h1>";
    var pics = listDir(PICS).filter(function (e) { return e.st.type === "file" && kindOf(e.path) === "image"; }).sort(newest);
    h += "<h3>Pictures</h3>" + (pics.length ? '<div class="pv-rows">' + pics.slice(0, 12).map(function (e) {
      var im = imageOf(e.path);
      return row(e.path, photoThumb(e.path, 44), e.name, (im && im.w ? Math.round(im.w) + " × " + Math.round(im.h) + "  ·  " : "") + A.ui.hsize(e.st.size));
    }).join("") + "</div>" : '<p class="pv-empty">Pictures you keep in ~/Pictures appear here.</p>');
    var ans = listDir(ANSWERS).filter(function (e) { return e.st.type === "file" && /\.md$/i.test(e.name); }).sort(newest).slice(0, 8);
    if (ans.length || A.claude) /* rdg: P14 no Answers section without an assistant */ h += "<h3>Answers</h3>" + (ans.length ? '<div class="pv-rows">' + ans.map(function (e) { return row(e.path, A.ui.fileIcon(e.path, { size: 34, plain: true }), answerTitle(e.path), A.ui.when(e.st.mtime)); }).join("") + "</div>"
      : '<p class="pv-empty">' + (A.claude ? "Every answer from ask and explain is kept here as a page you can read again." : "Answers from Claude are kept in ~/Documents/Answers. This copy of Atlas cannot reach Claude.") + "</p>");
    var shown = {}; pics.concat(ans).forEach(function (e) { shown[e.path] = 1; });
    var rec = recentList().filter(function (p) { return !shown[p]; }).slice(0, 8);
    if (rec.length) h += '<h3>Recent</h3><div class="pv-rows">' + rec.map(function (p) {
      var st = null; try { st = FS.stat(p); } catch (e) {}
      return row(p, kindOf(p) === "image" ? photoThumb(p, 44) : A.ui.fileIcon(p, { size: 34, plain: true }), FS.basename(p), A.tilde(FS.dirname(p)) + (st ? "  ·  " + A.ui.when(st.mtime) : ""));
    }).join("") + "</div>";
    h += "<h3>Manual</h3><p>" + ["reading-os", "atlas", "sh", "hier"] /* rdg: P16 */.filter(hasPage).map(function (n) { return linkHTML("man:" + n, "<code>man " + n + "</code>"); })
      .concat([linkHTML("man:", "All commands")]).join('<span class="pv-sep">·</span>') + "</p>";
    root.innerHTML = h;
    return root;
  }

  /* ---------- tables ---------- */
  function parseDelim(text, sep) {
    var rows = [], row = [], f = "", q = false, quoted = sep !== "\t", n = text.length;
    for (var i = 0; i < n; i++) {
      var c = text.charAt(i);
      if (q) { if (c === '"') { if (text.charAt(i + 1) === '"') { f += '"'; i++; } else q = false; } else f += c; continue; }
      if (c === '"' && quoted && f === "") { q = true; continue; }
      if (c === sep) { row.push(f); f = ""; continue; }
      if (c === "\n" || c === "\r") { if (c === "\r" && text.charAt(i + 1) === "\n") i++; row.push(f); rows.push(row); row = []; f = ""; continue; }
      f += c;
    }
    if (f !== "" || row.length) { row.push(f); rows.push(row); }
    rows.open = q;   // the text ended inside a quoted field
    return rows;
  }
  function sepFor(kind, text) {
    if (kind === "tsv") return "\t";
    var first = text.slice(0, (text.indexOf("\n") + 1 || text.length + 1) - 1);
    return first.indexOf(",") < 0 && first.indexOf(";") >= 0 ? ";" : first.indexOf(",") < 0 && first.indexOf("\t") >= 0 ? "\t" : ",";
  }
  var NUM = /^\s*[-+]?[$€£¥]?\s*(?:\d{1,3}(?:,\d{3})+|\d+)?(?:\.\d+)?(?:[eE][-+]?\d+)?\s*%?\s*$/;
  function isNum(v) { return /\d/.test(v) && NUM.test(v); }
  function numVal(v) { var x = parseFloat(String(v).replace(/[,$€£¥%\s]/g, "")); return isNaN(x) ? -Infinity : x; }
  var CAP = 1000, CHUNK = 500;   // rows drawn before "Show all"; after it, the rest in chunks the browser lays out only when seen
  function blankRow(r) { return r.every(function (c) { return c === ""; }); }
  function rowHTML(r, t) {
    var h = "<tr>";
    for (var i = 0; i < t.ncol; i++) { var v = r[i] == null ? "" : r[i]; h += "<td" + (t.num[i] ? ' class="n"' : "") + (v.length > 40 ? ' title="' + esc(v) + '"' : "") + ">" + esc(v) + "</td>"; }
    return h + "</tr>";
  }
  function sorter(t, s) {
    var c = s.c, numeric = t.num[c];
    return function (a, b) {
      var x = a[c] == null ? "" : a[c], y = b[c] == null ? "" : b[c];
      if (numeric) { x = numVal(x); y = numVal(y); } else { x = x.toLowerCase(); y = y.toLowerCase(); }
      return (x < y ? -1 : x > y ? 1 : 0) * s.d;
    };
  }
  function moreHTML(t) { return '<button type="button" class="btn small" data-act="all">Show all ' + t.view.length.toLocaleString("en-US") + " rows</button>"; }
  // a column is numeric when every value it has in the first 3,000 rows is a number
  function classify(t, rows, from) {
    for (var r = 0; r < rows.length && from + r < 3000; r++) for (var c = 0; c < t.ncol; c++) {
      var v = rows[r][c]; if (v == null || v === "") continue;
      t.seen[c] = true; if (t.okn[c] && !isNum(v)) t.okn[c] = false;
    }
  }
  function buildTable(page, info) {
    var root = el("div", "pv-doc pv-sheet selectable"), text = textOf(info), sep = sepFor(info.kind, text);
    var rows = parseDelim(text, sep), tail = [];
    while (rows.length && blankRow(rows[rows.length - 1])) tail.unshift(rows.pop());
    page.tbl = null;
    if (!rows.length) { root.innerHTML = '<p class="pv-empty">This table is empty.</p>'; return root; }
    var t = { text: text, sep: sep, head: rows[0], body: rows.slice(1), tail: tail, open: rows.open, ncol: 0, seen: [], okn: [], num: [] };
    rows.slice(0, 3000).forEach(function (r) { t.ncol = Math.max(t.ncol, r.length); });
    for (var c = 0; c < t.ncol; c++) { t.seen.push(false); t.okn.push(true); }
    classify(t, t.body, 0);
    t.num = t.seen.map(function (x, i) { return x && t.okn[i]; });
    var s = page.sort && page.sort.c < t.ncol ? page.sort : null;
    t.view = t.body.slice();
    if (s) t.view.sort(sorter(t, s));
    t.shown = page.allRows ? t.view.length : Math.min(t.view.length, CAP);
    var first = Math.min(t.shown, CAP);
    var html = '<div class="pv-tw"><table class="pv-t"><thead><tr>';
    for (var i = 0; i < t.ncol; i++) {
      var v = t.head[i] == null ? "" : t.head[i], on = s && s.c === i;
      html += "<th" + (t.num[i] ? ' class="n"' : "") + ' data-c="' + i + '" tabindex="0" aria-sort="' + (on ? (s.d > 0 ? "ascending" : "descending") : "none") + '" title="Sort by ' + esc(v || "column " + (i + 1)) + '">' + esc(v) + (on ? (s.d > 0 ? " ↑" : " ↓") : "") + "</th>";
    }
    html += "</tr></thead><tbody>";
    for (var k = 0; k < first; k++) html += rowHTML(t.view[k], t);
    html += '</tbody></table></div><div class="pv-more">' + (t.shown < t.view.length ? moreHTML(t) : "") + "</div>";
    root.innerHTML = html;
    t.wrap = root.querySelector(".pv-tw"); t.table = root.querySelector("table"); t.more = root.querySelector(".pv-more");
    t.parts = [{ tb: root.querySelector("tbody"), n: first }];
    t.rest = t.shown > first ? t.view.slice(first, t.shown) : null;   // drawn by drawRest once the page is on screen
    page.tbl = t;
    return root;
  }
  // Show all: the first 1,000 rows set the column widths; the rest follow as fixed-layout tables of 500 rows
  // with those widths, each laid out only when it scrolls into view (content-visibility), so a 20,000-row
  // table costs little more than its first screen, and a live change relays one chunk, not the whole table
  function chunkHTML(t, rows) {
    var h = '<div class="pv-chunk" style="contain-intrinsic-size: auto ' + rows.length * 31 + 'px"><table class="pv-t pv-tc" style="table-layout: fixed; width: ' + t.width + 'px"><colgroup>' +
      t.widths.map(function (w) { return '<col style="width: ' + w + 'px">'; }).join("") + "</colgroup><tbody>";
    for (var i = 0; i < rows.length; i++) h += rowHTML(rows[i], t);
    return h + "</tbody></table></div>";
  }
  function drawRest(page) {
    var t = page.tbl; if (!t || !t.rest) return;
    var rows = t.rest; t.rest = null;
    var ths = t.table.querySelectorAll("thead th"), widths = Array.prototype.map.call(ths, function (th) { return Math.round(th.getBoundingClientRect().width * 100) / 100; });
    var total = widths.reduce(function (a, b) { return a + b; }, 0);
    if (!(total > 0) || widths.some(function (w) { return !(w > 0); })) {   // not on screen (no layout): one table, as before
      t.parts[0].tb.insertAdjacentHTML("beforeend", rows.map(function (r) { return rowHTML(r, t); }).join(""));
      t.parts[0].n += rows.length;
      return;
    }
    t.widths = widths; t.width = Math.ceil(total);
    t.table.insertAdjacentHTML("afterbegin", "<colgroup>" + widths.map(function (w) { return '<col style="width: ' + w + 'px">'; }).join("") + "</colgroup>");
    t.table.style.tableLayout = "fixed"; t.table.style.width = t.width + "px";
    var html = ""; for (var i = 0; i < rows.length; i += CHUNK) html += chunkHTML(t, rows.slice(i, i + CHUNK));
    t.wrap.insertAdjacentHTML("beforeend", html);
    Array.prototype.forEach.call(t.wrap.querySelectorAll(".pv-chunk tbody"), function (tb) { t.parts.push({ tb: tb, n: tb.rows.length }); });
  }
