      ah.sort(function (x, y) { return x.r - y.r || (x.a.def.order || 100) - (y.a.def.order || 100); });
      ah.slice(0, 4).forEach(function (h) {
        var a = h.a, c = "open -a " + A.shQuote(a.name);
        ga.rows.push({ kind: "app", icon: appIcon(a), title: a.name, sub: a.def.desc || "Application", cmd: c, sh: c, rank: h.r, bias: 0, act: function () { close(); A.apps.launch(a); } });
      });
