    var calcApp = !!(A.calculator && A.calculator.open) && isFinite(+cv);
    if (cv != null) gk.rows.push({ kind: "calc", value: cv, icon: ic("calculator"), title: "= " + cv, mono: true, sub: t, smono: true, cmd: "calc " + A.shQuote(t) + " | pbcopy", alt: calcApp ? "open -a Calculator --args " + A.shArg(cv) : "", sh: "calc " + A.shQuote(t), rank: -1, bias: -10,
      act: function (how) { if (how && how.reveal && calcApp) { close(); A.calculator.open(cv); return; } copyValue(cv); } });
