  /* ==========================================================================
     Actions
     ========================================================================== */
  function openPath(abs, reveal) {
    try { A.open(abs, { reveal: !!reveal }); }
    catch (e) { if (A.toast) A.toast((e && e.message) || String(e)); return; }
    close();
  }
  function focusWin(w) { close(); if (w.hidden && w.app && A.wm.unhideApp) A.wm.unhideApp(w.app); w.focus(); }
  // a manual page opens on paper in Preview, which is what `open man:NAME` does; without Preview, man prints it
