      '<button type="button" class="sp-tab" hidden aria-label="Next reading (Tab)">tab</button>' +
      '<button type="button" class="sp-term" hidden title="Open in Terminal (⇧↩)" aria-label="Open in Terminal">' + A.icon("terminal", 16) + "</button></div>" +
      '<div class="sp-l" id="sp-list" role="listbox" aria-label="Results" hidden></div><div class="sp-p" hidden></div>';
    (document.getElementById("overlays") || document.body).appendChild(panel);
    glyphEl = panel.querySelector(".sp-g"); input = panel.querySelector(".sp-i"); tabEl = panel.querySelector(".sp-tab");
    termBtn = panel.querySelector(".sp-term"); listEl = panel.querySelector(".sp-l"); paperBox = panel.querySelector(".sp-p");
    glyphEl.innerHTML = glyph("search");

    input.addEventListener("input", function () { if (!input.value) pin = null; forceResults = false; update(); });
    input.addEventListener("keydown", onFieldKey);
    glyphEl.addEventListener("click", function () { cycle(1); focusField(); });
    tabEl.addEventListener("click", function () { cycle(1); focusField(); });
    termBtn.addEventListener("click", function () { toTerminal(); });
    // the field keeps the keyboard: clicks on the glass or the rows never take it away
