    listEl.addEventListener("pointerdown", function (e) { e.preventDefault(); });
    listEl.addEventListener("pointermove", function (e) {
      if (lastPt && lastPt.x === e.clientX && lastPt.y === e.clientY) return;   // a scroll under a resting pointer is not a choice
      lastPt = { x: e.clientX, y: e.clientY };
      var row = e.target.closest && e.target.closest(".sp-r"); if (row) select(+row.getAttribute("data-i"), { noScroll: true });
    });
    listEl.addEventListener("click", function (e) { var row = e.target.closest && e.target.closest(".sp-r"); if (row) activate(+row.getAttribute("data-i"), { reveal: e.altKey }); });
