    if (!openFlag || !panel || view !== "results") return;
    var r2 = analyze(input.value, cwdNow()), m2 = effective(r2), x = collect(r2, m2), keys = x.rows.map(rowKey);
    if (m2 === mode && keys.join("\n") === res.rows.map(rowKey).join("\n")) return;   // nothing that shows changed
